CREATE OR REPLACE FUNCTION calc_effective_leverage(
    leverage_scale numeric,
    position_value numeric,
    balance numeric
) RETURNS numeric AS $$
BEGIN
    RETURN leverage_scale * (position_value / balance);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calc_effective_leverage(
    leverage_scale numeric,
    position_value numeric,
    balance numeric
) RETURNS numeric AS $$
BEGIN
    RETURN leverage_scale * (position_value / balance);
END;
$$ LANGUAGE plpgsql;

